import os,re
pats={
 "Render key rnd_":  re.compile(r'rnd_[A-Za-z0-9_-]{20,}'),
 "GitHub ghp_":      re.compile(r'ghp_[A-Za-z0-9]{30,}'),
 "GitHub pat":       re.compile(r'github_pat_[A-Za-z0-9_]{30,}'),
 "Vercel vck_":      re.compile(r'vck_[A-Za-z0-9]{20,}'),
 "AWS AKIA":         re.compile(r'AKIA[A-Z0-9]{16}'),
 "Twilio SID AC":    re.compile(r'AC[a-f0-9]{32}'),
 "Twilio key SK":    re.compile(r'SK[a-f0-9]{32}'),
 "Supabase sbp_":    re.compile(r'sbp_[a-f0-9]{40}'),
 "Postgres URI":     re.compile(r'postgres(?:ql)?://[^\s"\'<>]{20,}'),
}
skip={"node_modules",".git",".rork","qa-frames","tmp_frames","qa-archive"}
hits={k:{} for k in pats}
scanned=0
for root,dirs,files in os.walk("."):
    dirs[:]=[d for d in dirs if d not in skip]
    for f in files:
        p=os.path.join(root,f)
        try:
            if os.path.getsize(p)>3_000_000: continue
            t=open(p,errors="replace").read()
        except Exception: continue
        scanned+=1
        for k,rx in pats.items():
            for m in set(rx.findall(t)):
                # store only the distinct secret's fingerprint, never the value
                hits[k].setdefault(m,set()).add(p)
print(f"scanned {scanned} files (excluding node_modules/.git/.rork/frames)\n")
for k,v in hits.items():
    if not v: print(f"{k:18} -> none"); continue
    print(f"{k:18} -> {len(v)} distinct value(s)")
    for val,paths in v.items():
        tag = val[:8]+"…"+val[-3:] if len(val)>14 else "(short)"
        ex=sorted(paths)[:3]
        print(f"     {tag:16} in {len(paths)} file(s): {', '.join(ex)}")
